import { useState, useRef } from 'react';

type Props = { onSubmit: (value: { email: string; password: string; terms: boolean }) => void };

export default function Signup({ onSubmit }: Props) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [terms, setTerms] = useState(false);
  const [error, setError] = useState<{ field: string; message: string } | null>(null);
  const emailRef = useRef<HTMLInputElement>(null);
  const passwordRef = useRef<HTMLInputElement>(null);
  const termsRef = useRef<HTMLInputElement>(null);

  function submit() {
    // clear previous error
    setError(null);
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      const err = { field: 'email', message: 'Enter a valid email address.' };
      setError(err);
      emailRef.current?.focus();
      return;
    }
    if (password.length < 8) {
      const err = { field: 'password', message: 'Use at least 8 characters.' };
      setError(err);
      passwordRef.current?.focus();
      return;
    }
    if (!terms) {
      const err = { field: 'terms', message: 'Accept the terms to continue.' };
      setError(err);
      termsRef.current?.focus();
      return;
    }
    onSubmit({ email, password, terms });
  }

  return (
    <form noValidate onSubmit={e => {
      e.preventDefault();
      submit();
    }}>
      <h1>Create your account</h1>
      <div className="field">
        <label htmlFor="email-input">Email</label>
        <input
          id="email-input"
          data-testid="email"
          type="email"
          value={email}
          placeholder="you@example.com"
          onChange={e => setEmail(e.target.value)}
          ref={emailRef}
          aria-invalid={error?.field === 'email' ? 'true' : undefined}
          aria-describedby={error?.field === 'email' ? 'email-error' : undefined}
        />
        {error?.field === 'email' && (
          <p id="email-error" className="form-error" hidden={false}>
            {error.message}
          </p>
        )}
      </div>
      <div className="field">
        <label htmlFor="password-input">Password</label>
        <input
          id="password-input"
          data-testid="password"
          type="password"
          value={password}
          placeholder="At least 8 characters"
          onChange={e => setPassword(e.target.value)}
          ref={passwordRef}
          aria-invalid={error?.field === 'password' ? 'true' : undefined}
          aria-describedby={error?.field === 'password' ? 'password-error' : undefined}
        />
        {error?.field === 'password' && (
          <p id="password-error" className="form-error" hidden={false}>
            {error.message}
          </p>
        )}
      </div>
      <label className="terms">
        <input
          id="terms-input"
          data-testid="terms"
          type="checkbox"
          checked={terms}
          onChange={e => setTerms(e.target.checked)}
          ref={termsRef}
          aria-invalid={error?.field === 'terms' ? 'true' : undefined}
          aria-describedby={error?.field === 'terms' ? 'terms-error' : undefined}
        />
        I agree to the terms
        {error?.field === 'terms' && (
          <p id="terms-error" className="form-error" hidden={false}>
            {error.message}
          </p>
        )}
      </label>
      {/* Live region for screen readers */}
      {error && <div role="alert" aria-live="assertive" className="sr-only">{error.message}</div>}
      <button type="submit" className="submit" data-testid="submit">
        Create account
      </button>
    </form>
  );
}

